// Fixed public game art/bindings only; private owner code input, no route or source lookup.
const RECORDS=[{"kind":"art","bytes":170638,"sha256":"356280fac3d0b4719ce31aa9e263b5de5a2797e191600f178c3fa4e53d1711de","gzipBytes":30209,"gzipSha256":"975f77cde2dc9725574fac39429285ba0053b2591fcfd9e60df74b380d37b2c7","base64":""},{"kind":"bindings","bytes":243447,"sha256":"5b0fd206fda2e0ba7d4161008eab6f0b4c7d73116478f2bfb899d16b2a9b676e","gzipBytes":22547,"gzipSha256":"184cae27daa94c1e4808de7ca6d28a0aafe4290316debd9f6dbe65c8e67ad07c","base64":""}];
export class DiscoveryStaticError extends Error{}
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function discoveryStaticBytes(){const out={};for(const r of RECORDS){if(r.bytes<1||r.bytes>2097152||r.gzipBytes<1||r.gzipBytes>1048576)throw new DiscoveryStaticError('static_bounds');const zipped=Uint8Array.from(atob(r.base64),c=>c.charCodeAt(0));if(zipped.length!==r.gzipBytes||await sha(zipped)!==r.gzipSha256)throw new DiscoveryStaticError('static_compressed_sha');const reader=new Blob([zipped]).stream().pipeThrough(new DecompressionStream('gzip')).getReader(),chunks=[];let n=0;try{for(;;){const p=await reader.read();if(p.done)break;n+=p.value.length;if(n>r.bytes)throw new DiscoveryStaticError('static_decompressed_bound');chunks.push(p.value);}}catch(e){try{await reader.cancel();}catch{}throw new DiscoveryStaticError('static_decode');}finally{reader.releaseLock();}if(n!==r.bytes)throw new DiscoveryStaticError('static_decompressed_size');const raw=new Uint8Array(n);let at=0;for(const p of chunks){raw.set(p,at);at+=p.length;}if(await sha(raw)!==r.sha256)throw new DiscoveryStaticError('static_raw_sha');out[r.kind]={raw,expectedSha256:r.sha256};}return out;}
